/* ============================ Rendering ============================ */
// Rank/status class -> the CSS class applied to a <td>.
const CELL_CLASS = { r1: "r1", r2: "r2", r3: "r3", fail: "fail", na: "na" };

const isOurs = (method) => method[0].startsWith("Ours");

// A method header: name over venue, underlined by category (opt vs. feed-forward),
// mirroring the paper's \catOpt / \catReg encoding.
function methodName(method) {
  return `<span class="cat cat-${method[2]}">${method[0]}</span>`;
}

function cellTd(cell, extraClass = "") {
  const [value, rank] = cell;
  const cls = [rank ? CELL_CLASS[rank] : "", extraClass].filter(Boolean).join(" ");
  return `<td${cls ? ` class="${cls}"` : ""}>${value}</td>`;
}

// Build a <colgroup>: the first `nHead` columns get `headW`, the rest share the remainder.
function colgroup(nHead, headW, nData) {
  let cg = "<colgroup>";
  for (let i = 0; i < nHead; i++) cg += `<col style="width:${headW}" />`;
  const w = `${(100 - parseFloat(headW) * nHead) / nData}%`;
  for (let i = 0; i < nData; i++) cg += `<col style="width:${w}" />`;
  return cg + "</colgroup>";
}

// Per-scene table (ETH3D): every method spans `subHeaders` sub-columns (RRA/RTA),
// and the method list may be split into threshold blocks (@5deg then @1deg).
function renderSceneTable(blocks, subHeaders, rows, avgRow) {
  const sub = subHeaders.length;
  const methods = blocks.flatMap((b) => b.methods);
  const cg = colgroup(1, "7%", methods.length * sub);

  // Column index (in sub-column units) at which each threshold block starts.
  const blockStarts = [];
  let seen = 0;
  for (const b of blocks) {
    blockStarts.push(seen);
    seen += b.methods.length;
  }
  const dividerAt = new Set(blockStarts.slice(1));
  const flag = (i) => {
    const classes = [];
    if (isOurs(methods[i])) classes.push("ours");
    if (dividerAt.has(i)) classes.push("blk-div");
    return classes.join(" ");
  };

  let head = "<thead><tr><th class=\"row-head\"></th>";
  blocks.forEach((b, bi) => {
    const div = bi > 0 ? " blk-div" : "";
    head += `<th class="group-head${div}" colspan="${b.methods.length * sub}">${b.label}</th>`;
  });
  head += "</tr><tr><th class=\"row-head\">Scene</th>";
  methods.forEach((m, i) => {
    head += `<th class="${flag(i)}" colspan="${sub}">${methodName(m)}</th>`;
  });
  head += "</tr><tr><th class=\"row-head\"></th>";
  methods.forEach((m, i) => {
    head += `<th class="venue-cell ${flag(i)}" colspan="${sub}">${m[1] || "&nbsp;"}</th>`;
  });
  head += "</tr><tr><th class=\"row-head\"></th>";
  methods.forEach((m, i) => {
    subHeaders.forEach((s, j) => {
      head += `<th class="subh ${j === 0 ? flag(i) : ""}">${s}</th>`;
    });
  });
  head += "</tr></thead>";

  const bodyRow = (r, isAvg) => {
    let tds = `<td class="row-head">${r[0]}</td>`;
    for (let k = 1; k < r.length; k++) {
      const methodIdx = Math.floor((k - 1) / sub);
      const subIdx = (k - 1) % sub;
      tds += cellTd(r[k], subIdx === 0 ? flag(methodIdx) : "");
    }
    return `<tr class="${isAvg ? "avg-row" : ""}">${tds}</tr>`;
  };
  let body = "<tbody>";
  rows.forEach((r) => (body += bodyRow(r, false)));
  body += bodyRow(avgRow, true);
  body += "</tbody>";

  return `<div class="table-scroll"><table class="data">${cg}${head}${body}</table></div>`;
}

// Metric-as-rows table (IMC2021, T&T): methods are columns, metrics are rows.
// The metric-label column narrows as the method count grows, so wide tables give
// their data columns enough room to show full method names.
function renderMetricTable(methods, rows) {
  const cg = colgroup(1, methods.length > 16 ? "8%" : "12%", methods.length);
  const oursFrom = methods.findIndex(isOurs);
  const flag = (i) => (i === oursFrom ? "ours" : "");

  let head = '<thead><tr><th class="row-head">Metric</th>';
  methods.forEach((m, i) => (head += `<th class="${flag(i)}">${methodName(m)}</th>`));
  head += '</tr><tr><th class="row-head"></th>';
  methods.forEach((m, i) => {
    head += `<th class="venue-cell ${flag(i)}">${m[1] || "&nbsp;"}</th>`;
  });
  head += "</tr></thead>";

  let body = "<tbody>";
  rows.forEach((r) => {
    let tds = `<td class="row-head">${r[0]}</td>`;
    for (let k = 1; k < r.length; k++) tds += cellTd(r[k], flag(k - 1));
    body += `<tr>${tds}</tr>`;
  });
  body += "</tbody>";
  return `<div class="table-scroll"><table class="data">${cg}${head}${body}</table></div>`;
}

// FastMap table: `groups.length` metric groups over the same methods, scenes as
// rows. `splitAfter` is the row count above which splits use COLMAP ground truth.
function renderFastMap(methods, groups, rows, splitAfter) {
  const nm = methods.length;
  const cg = colgroup(2, "9%", nm * groups.length);
  let head =
    '<thead><tr><th class="row-head" rowspan="2">Scene</th><th class="row-head" rowspan="2">#imgs</th>';
  groups.forEach((g, gi) => {
    head += `<th colspan="${nm}" class="group-head${gi > 0 ? " grp-div" : ""}">${g}</th>`;
  });
  head += '</tr><tr>';
  groups.forEach(() => {
    methods.forEach((m, i) => {
      const cls = ["subh", i === 0 ? "grp-div" : "", isOurs(m) ? "ours-sub" : ""];
      head += `<th class="${cls.filter(Boolean).join(" ")}">${methodName(m)}</th>`;
    });
  });
  head += "</tr></thead>";

  let body = "<tbody>";
  rows.forEach((r, ri) => {
    let tds = `<td class="row-head">${r[0]}</td>${cellTd(r[1])}`;
    for (let k = 2; k < r.length; k++) {
      tds += cellTd(r[k], (k - 2) % nm === 0 ? "grp-div" : "");
    }
    body += `<tr class="${ri === splitAfter ? "split-row" : ""}">${tds}</tr>`;
  });
  body += "</tbody>";
  return `<div class="table-scroll"><table class="data">${cg}${head}${body}</table></div>`;
}

function block(id, title, caption, html) {
  return `<div class="table-block" id="${id}"><h3>${title}</h3><p class="tbl-caption">${caption}</p>${html}</div>`;
}

document.addEventListener("DOMContentLoaded", () => {
  const root = document.getElementById("tables");
  if (!root) throw new Error("missing #tables container in index.html");
  const parts = [];

  parts.push(block(
    "tab-eth3d",
    "Table 1 &mdash; SfM on ETH3D",
    "Relative rotation / translation accuracy (RRA / RTA) at the 5&deg; (left) and 1&deg; (right) thresholds, following the Glob3R protocol. Baseline numbers from MBA, AMB3R, and Glob3R.",
    renderSceneTable(
      [
        { label: "Threshold @5&deg;", methods: ETH3D_METHODS_5 },
        { label: "Threshold @1&deg;", methods: ETH3D_METHODS_1 },
      ],
      ["RRA", "RTA"],
      ETH3D_ROWS,
      ETH3D_AVG
    )
  ));

  parts.push(block(
    "tab-imc",
    "Table 2 &mdash; Pose estimation on IMC2021",
    "AUC of pose error at 3&deg; / 5&deg; / 10&deg;. Baseline numbers from DF-SfM and DGSfM.",
    renderMetricTable(IMC_METHODS, IMC_ROWS)
  ));

  parts.push(block(
    "tab-tnt",
    "Table 3 &mdash; SfM on Tanks &amp; Temples",
    "RRA / RTA at 5&deg; and ATE, averaged across all 21 scenes. Baseline numbers from SAIL and MBA.",
    renderMetricTable(TNT_METHODS, TNT_ROWS)
  ));

  parts.push(block(
    "tab-fastmap",
    "Table 4 &mdash; Pose accuracy on the FastMap benchmark",
    "ATE (&darr;), AUC@3 (&uarr;), and RTA@3 (&uarr;) across eleven large-scale splits. Baseline numbers from FastMap. Splits above the rule use a COLMAP reconstruction as ground truth; those below do not. " +
      '<span class="legend-chip chip-fail">failure</span> ' +
      '<span class="legend-chip chip-na">timeout</span>',
    renderFastMap(FM_METHODS, FM_GROUPS, FM_ROWS, FM_SPLIT_AFTER)
  ));

  root.innerHTML = parts.join("");
});
